package com.medicare360.patient; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/patients") @CrossOrigin(origins="http://localhost:4200") public class PatientController { private final PatientRepository repo; public PatientController(PatientRepository repo){this.repo=repo;} @GetMapping public List<Patient> all(){return repo.findAll();} @GetMapping("/{id}") public Patient one(@PathVariable Long id){return repo.findById(id).orElseThrow();} @PostMapping public Patient create(@RequestBody Patient p){return repo.save(p);} @PutMapping("/{id}") public Patient update(@PathVariable Long id,@RequestBody Patient p){Patient x=repo.findById(id).orElseThrow(); x.setName(p.getName());x.setEmail(p.getEmail());x.setPhone(p.getPhone());x.setDateOfBirth(p.getDateOfBirth());return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }